tape( 'the method should not invoke a provided callback function if operating on an empty complex number array (complex128)', function test( t ) {
	var Complex128Array;
	var arr;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array();
	arr.forEach( fcn );

	t.end();

	function fcn() {
		t.fail( 'should not be invoked' );
	}
});

