tape( 'the method returns `undefined` (complex128)', function test( t ) {
	var Complex128Array;
	var arr;
	var out;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	out = arr.forEach( fcn );

	t.strictEqual( out, void 0, 'returns expected value' );
	t.end();

	function fcn( v ) {
		if ( !isComplex128( v ) ) {
			t.fail( 'should be a complex number' );
		}
	}
});

