tape( 'the method invokes a provided function for each element in an array (complex128)', function test( t ) {
	var Complex128Array;
	var expected;
	var arr;

	Complex128Array = factory( 'complex128' );
	expected = [];
	arr = new Complex128Array( [ 1.0, 1.0, 2.0, -2.0 ] );
	arr.forEach( fcn );
	expected = new Complex128Array( expected );

	t.deepEqual( reinterpret128( expected, 0 ), reinterpret128( arr, 0 ), 'returns expected value' );
	t.end();

	function fcn( v ) {
		expected.push( v );
	}
});

