tape( 'the method supports providing an execution context (complex128)', function test( t ) {
	var Complex128Array;
	var ctx;
	var arr;

	Complex128Array = factory( 'complex128' );
	ctx = {
		'count': 0
	};
	arr = new Complex128Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, 3.0 ] );
	arr.forEach( fcn, ctx );

	t.strictEqual( ctx.count, 3, 'returns expected value' );
	t.end();

	function fcn() {
		this.count += 1; // eslint-disable-line no-invalid-this
	}
});

